export const SURVIVOR_PERK_EFFECTS: Readonly<Record<string, readonly PerkEffect[]>> = Object.fromEntries(
  Object.entries(effects).map(([id, value]) => [`survivor-${id}`, value])
);

function mul(stat: string, value: number, condition?: EffectCondition, duration?: number, calculationMode?: PerkEffect["calculationMode"]): PerkEffect {
  return { stat, operation: "multiply", interpretation: "verified", value, unit: "multiplier", ...(condition ? { condition } : {}), ...(duration === undefined ? {} : { duration }), ...(calculationMode ? { calculationMode } : {}) };
}
function add(stat: string, value: number, unit: EffectUnit, condition?: EffectCondition): PerkEffect {
  return { stat, operation: "add", interpretation: "verified", value, unit, ...(condition ? { condition } : {}) };
}
function set(stat: string, value: number, unit: EffectUnit, condition?: EffectCondition): PerkEffect {
  return { stat, operation: "set", interpretation: "verified", value, unit, ...(condition ? { condition } : {}) };
}
function note(effect: PerkEffect, detail: string): PerkEffect { return { ...effect, detail }; }
function info(label: string, detail: string, condition?: EffectCondition, duration?: number): PerkEffect {
  return { stat: "survivor.mechanic", label, detail, operation: "apply_status", interpretation: "verified", value: true, unit: "boolean", ...(condition ? { condition } : {}), ...(duration === undefined ? {} : { duration }) };
}
function aura(target: "killer" | "survivor", label: string, detail: string, condition?: EffectCondition, duration?: number, range?: number): PerkEffect {
  return { ...info(label, detail, condition, duration), stat: `${target}.aura`, operation: "reveal", ...(range === undefined ? {} : { range }) };
}
function status(id: string, label: string, duration: number | null, condition?: EffectCondition, detail?: string): PerkEffect {
  return { ...info(label, detail ?? "", condition), stat: `survivor.status.${id}`, duration };
}
function exhausted(duration: number, condition: EffectCondition, detail: string): PerkEffect {
  return status("exhausted", "Épuisement", duration, condition, detail + " Le délai ne récupère normalement pas pendant la course ; ce n’est pas un cooldown classique de perk.");
}
function heal(label: string, detail: string, condition: EffectCondition): PerkEffect {
  return info(label, detail + " Un état correspond à 16 charges de soin ; les restrictions de Brisé/Blessure profonde restent à vérifier.", condition);
}
function blessing(detail = ""): PerkEffect {
  return info("Bénédiction : préparation et zone", "14 s sur totem passif, 28 s sur ensorcelé ; rayon standard 24 m, un seul totem porte vos bénédictions. Plusieurs exemplaires identiques ne se cumulent pas. " + detail, boon);
}
function opponent(value: number, duration: number, detail: string): PerkEffect {
  return note(mul("opponent.speed", value, trigger, duration), detail + " Vitesse illustrée pour un tueur à 4,6 m/s ; la vitesse et les pouvoirs réels du tueur adverse ne sont pas fournis.");
}
